class TestTransactionControllerForcedLmdbExecutionStrategy {

	private static final String NESTED_LOOP = "nestedLoop";
	private static final String BOGUS_STRATEGY = "totally-bogus-strategy-name";
	private static final String QUERY = "PREFIX ex: <http://example.com/> "
			+ "ASK { ?person ex:worksAt ex:acme }";
	private static final String JOIN_QUERY = "PREFIX ex: <http://example.com/> "
			+ "SELECT ?person WHERE { ?person ex:knows ?other . "
			+ "?person ex:worksAt ?company . ?other ex:worksAt ?company }";

	@TempDir
	File dataDirectory;

	private Repository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new LmdbStore(dataDirectory,
				new LmdbStoreConfig("spoc,posc,ospc")
						.setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(true)));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(Values.iri("http://example.com/alice"), Values.iri("http://example.com/knows"),
					Values.iri("http://example.com/bob"));
			connection.add(Values.iri("http://example.com/alice"), Values.iri("http://example.com/worksAt"),
					Values.iri("http://example.com/acme"));
			connection.add(Values.iri("http://example.com/bob"), Values.iri("http://example.com/worksAt"),
					Values.iri("http://example.com/acme"));
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void transactionQueryHonorsForcedStrategy() throws Exception {
		withTransaction(repository, transaction -> {
			MockHttpServletRequest request = newRequest(transaction.getID(), QUERY, NESTED_LOOP, null);
			ModelAndView result = new TransactionController().handleRequestInternal(request,
					new MockHttpServletResponse());
			assertThat(result.getModel()).containsEntry(QueryResultView.QUERY_RESULT_KEY, true);
		});
	}

	@Test
	void transactionQueryRejectsUnknownForcedStrategy() throws Exception {
		withTransaction(repository, transaction -> {
			MockHttpServletRequest request = newRequest(transaction.getID(), QUERY, BOGUS_STRATEGY, null);
			assertThatThrownBy(() -> new TransactionController().handleRequestInternal(request,
					new MockHttpServletResponse()))
							.isInstanceOfSatisfying(ServerHTTPException.class,
									error -> assertThat(error.getStatusCode()).isEqualTo(503));
		});
	}

	@Test
	void transactionExplainUsesForcedStrategy() throws Exception {
		withTransaction(repository, transaction -> {
			MockHttpServletRequest request = newRequest(transaction.getID(), JOIN_QUERY, NESTED_LOOP,
					Explanation.Level.Executed.name());
			ModelAndView result = new TransactionController().handleRequestInternal(request,
					new MockHttpServletResponse());
			Explanation explanation = (Explanation) result.getModel()
					.get(QueryResultView.QUERY_EXPLAIN_RESULT_KEY);
			assertThat(explanation.toString()).contains("nativeExecutionPath=" + NESTED_LOOP);
		});
	}

	@Test
	void transactionExplainRejectsUnknownForcedStrategy() throws Exception {
		withTransaction(repository, transaction -> {
			MockHttpServletRequest request = newRequest(transaction.getID(), JOIN_QUERY, BOGUS_STRATEGY,
					Explanation.Level.Optimized.name());
			assertThatThrownBy(() -> new TransactionController().handleRequestInternal(request,
					new MockHttpServletResponse()))
							.isInstanceOfSatisfying(ServerHTTPException.class,
									error -> assertThat(error.getStatusCode()).isEqualTo(503));
		});
	}

	@Test
	void unsetStrategyAndNonLmdbRepositoryRemainAdaptive() throws Exception {
		withTransaction(repository, transaction -> {
			MockHttpServletRequest request = newRequest(transaction.getID(), QUERY, null, null);
			ModelAndView result = new TransactionController().handleRequestInternal(request,
					new MockHttpServletResponse());
			assertThat(result.getModel()).containsEntry(QueryResultView.QUERY_RESULT_KEY, true);

			request = newRequest(transaction.getID(), QUERY,
					Protocol.LMDB_FORCED_EXECUTION_STRATEGY_NOT_ACTIVATED, null);
			result = new TransactionController().handleRequestInternal(request, new MockHttpServletResponse());
			assertThat(result.getModel()).containsEntry(QueryResultView.QUERY_RESULT_KEY, true);

			request = newRequest(transaction.getID(), QUERY, " \t", null);
			result = new TransactionController().handleRequestInternal(request, new MockHttpServletResponse());
			assertThat(result.getModel()).containsEntry(QueryResultView.QUERY_RESULT_KEY, true);
		});

		Repository memoryRepository = new SailRepository(new MemoryStore());
		memoryRepository.init();
		try {
			withTransaction(memoryRepository, transaction -> {
				MockHttpServletRequest request = newRequest(transaction.getID(), "ASK { }", BOGUS_STRATEGY, null);
				ModelAndView result = new TransactionController().handleRequestInternal(request,
						new MockHttpServletResponse());
				assertThat(result.getModel()).containsEntry(QueryResultView.QUERY_RESULT_KEY, true);
			});
		} finally {
			memoryRepository.shutDown();
		}
	}

	private static MockHttpServletRequest newRequest(UUID transactionId, String query, String forcedStrategy,
			String explainLevel) {
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.setRequestURI("/repositories/test-repo/transactions/" + transactionId);
		request.setPathInfo("test-repo/transactions/" + transactionId);
		request.setMethod(HttpMethod.PUT.name());
		request.setCharacterEncoding(StandardCharsets.UTF_8.name());
		request.setContentType("application/sparql-query; charset=utf-8");
		request.setContent(query.getBytes(StandardCharsets.UTF_8));
		request.setParameter(Protocol.ACTION_PARAM_NAME, Protocol.Action.QUERY.toString());
		if (forcedStrategy != null) {
			request.setParameter(Protocol.LMDB_FORCED_EXECUTION_STRATEGY_PARAM_NAME, forcedStrategy);
		}
		if (explainLevel != null) {
			request.setParameter(Protocol.EXPLAIN_PARAM_NAME, explainLevel);
		}
		request.addHeader("Accept", "application/json");
		return request;
	}

	private static void withTransaction(Repository targetRepository, TransactionAction action) throws Exception {
		Transaction transaction = new Transaction(targetRepository);
		ActiveTransactionRegistry.INSTANCE.register(transaction);
		try {
			action.run(transaction);
		} finally {
			try {
				transaction.close();
			} finally {
				ActiveTransactionRegistry.INSTANCE.deregister(transaction);
			}
		}
	}

	@FunctionalInterface
	private interface TransactionAction {
		void run(Transaction transaction) throws Exception;
	}
}
